const doc = $input.first().json;
const mail = $('Normalize Email').first().json;

const documentText = String(doc.document_text || '').slice(0, 15000);
const requestId = String(mail.requestId || ('req_' + $execution.id));

const systemPrompt = 'You are an email triage engine for an operations inbox. Classify the email and extract fields. '
  + 'Respond with ONLY one valid JSON object, no markdown. '
  + 'Schema: {"email_type": "urgent" | "request" | "invoice" | "routine", '
  + '"summary": one short sentence, '
  + '"action_required": what a human should do next, or empty string, '
  + '"sender_name": string or null, "vendor": string or null, "po_number": string or null, '
  + '"invoice_number": string or null, "invoice_date": "YYYY-MM-DD" or null, "due_date": "YYYY-MM-DD" or null, '
  + '"currency": three-letter code or null, "amount": number or null, "confidence": number 0-1}. '
  + 'Rules: invoice = bill, purchase order or remittance; request = someone asking for something; '
  + 'urgent = deadline, complaint or escalation; routine = newsletter, FYI, notification. '
  + 'Extract only values present in the email or attachment. Never invent values.';

const userContent = 'From: ' + mail.from
  + '\nSubject: ' + mail.subject
  + '\nEmail body: ' + String(mail.bodyText || '').slice(0, 3000)
  + '\nAttachment text:\n' + documentText;

const requestBody = {
  model: 'deepseek-chat',
  temperature: 0,
  max_tokens: 600,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return [{ json: { request_body: requestBody, request_id: requestId, document_text: documentText } }];

const meta = $('Build Classify Request').first().json;
const mail = $('Normalize Email').first().json;
const raw = $input.first().json;

let content = '';
if (raw && raw.choices && raw.choices[0] && raw.choices[0].message) {
  content = String(raw.choices[0].message.content || '');
}

let parsed = null;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
if (start !== -1 && end > start) {
  try {
    parsed = JSON.parse(content.slice(start, end + 1));
  } catch (e) {
    parsed = null;
  }
}

function cleanField(value) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/[\r\n]+/g, ' ').replace(/,/g, ' ').trim();
}
function cleanDate(value) {
  const match = String(value || '').match(/^\d{4}-\d{2}-\d{2}$/);
  return match ? match[0] : '';
}
function toAmount(value) {
  const n = Number(String(value === null || value === undefined ? '' : value).replace(/[^0-9.-]/g, ''));
  return isFinite(n) ? n : 0;
}

const allowedTypes = ['urgent', 'request', 'invoice', 'routine'];
const errors = [];

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  errors.push({ field: 'document', message: 'The AI service did not return a valid JSON object.' });
}

const emailType = parsed && parsed.email_type ? cleanField(parsed.email_type).toLowerCase() : '';
const summary = parsed ? cleanField(parsed.summary) : '';

if (parsed && allowedTypes.indexOf(emailType) === -1) {
  errors.push({ field: 'email_type', message: 'Must be one of: urgent, request, invoice, routine. Got "' + emailType + '".' });
}
if (parsed && !summary) {
  errors.push({ field: 'summary', message: 'A one-line summary is required.' });
}

const invoiceNumber = parsed ? cleanField(parsed.invoice_number) : '';
const amount = parsed ? toAmount(parsed.amount) : 0;
const invoiceDate = parsed ? cleanDate(parsed.invoice_date) : '';
const dueDate = parsed ? cleanDate(parsed.due_date) : '';

let incomplete = false;
if (parsed && emailType === 'invoice') {
  if (!invoiceNumber) incomplete = true;
  if (amount <= 0) incomplete = true;
  if (!dueDate && !invoiceDate) incomplete = true;
}

let hash = 5381;
const hashSource = meta.document_text + '|' + mail.subject;
for (let i = 0; i < hashSource.length; i++) {
  hash = ((hash << 5) + hash + hashSource.charCodeAt(i)) | 0;
}

const valid = errors.length === 0;
const vendor = parsed ? cleanField(parsed.vendor) : '';
const needsApproval = emailType === 'invoice' || emailType === 'request' || emailType === 'urgent';
const status = needsApproval ? (incomplete ? 'needs_review' : 'pending_approval') : 'logged';
const dedupeKey = valid
  ? (invoiceNumber
      ? ('invoice|' + invoiceNumber.toLowerCase())
      : (emailType + '|hash-' + String(hash)))
  : '';
const archivedFile = valid
  ? ((emailType + '_' + (invoiceNumber || 'msg') + '_' + $execution.id + '.txt').replace(/[^0-9A-Za-z._-]/g, '_'))
  : '';

return [{
  json: {
    valid: valid,
    errors: errors,
    incomplete: incomplete,
    request_id: meta.request_id,
    message_type: emailType,
    is_urgent: emailType === 'urgent',
    sender: cleanField(mail.from),
    subject: cleanField(mail.subject),
    sender_name: parsed ? cleanField(parsed.sender_name) : '',
    summary: summary,
    action_required: parsed ? cleanField(parsed.action_required) : '',
    vendor: vendor,
    po_number: parsed ? cleanField(parsed.po_number) : '',
    invoice_number: invoiceNumber,
    invoice_date: invoiceDate,
    due_date: dueDate,
    amount: amount,
    currency: parsed ? cleanField(parsed.currency).toUpperCase() : '',
    confidence: parsed ? Number(parsed.confidence || 0) : 0,
    needs_approval: needsApproval,
    status: status,
    dedupe_key: dedupeKey,
    archived_file: archivedFile,
    attachment_name: cleanField(mail.attachmentName),
    document_text: meta.document_text
  }
}];

const rows = $input.all().map(function (item) { return item.json; });
let total = 0;
const lines = [];
for (const row of rows) {
  const count = Number(row.total || 0);
  total += count;
  lines.push('- ' + row.message_type + ' (' + row.status + '): ' + count);
}
if (lines.length === 0) lines.push('- no messages in the last 24 hours');

return [{
  json: {
    subject: 'Morning inbox digest: ' + total + ' message(s) in the last 24h',
    body: 'Inbox digest for the last 24 hours\n\n' + lines.join('\n') + '\n\nItems marked pending_approval are waiting for a human decision.',
    generated_at: new Date().toISOString()
  }
}];

const mail = $('Normalize Email').first().json;
const content = String(mail.attachmentBase64 || '');
const mimeType = String(mail.attachmentMimeType || 'application/pdf');

if (!content) {
  return [{ json: { vision_request: null } }];
}

return [{ json: { vision_request: { requests: [ { inputConfig: { content: content, mimeType: mimeType }, features: [ { type: 'DOCUMENT_TEXT_DETECTION' } ] } ] } } }];

const raw = $input.first().json;

let text = '';
try {
  const pages = raw && raw.responses && raw.responses[0] && raw.responses[0].responses;
  if (Array.isArray(pages)) {
    text = pages.map(function (page) {
      if (!page) return '';
      if (page.fullTextAnnotation && page.fullTextAnnotation.text) return page.fullTextAnnotation.text;
      return '';
    }).filter(Boolean).join('\n');
  }
} catch (e) {
  text = '';
}

text = String(text || '').trim();

return [{ json: { document_text: text, extraction_empty: !text, ocr_used: true } }];
